"""Install short notification text without sending any notification."""
import os,hashlib,base64,fcntl,subprocess,time,tempfile,shutil
from pathlib import Path
MANIFEST={'send_home_assistant_notification.ps1': {'old': '9b559cd50abb7cfa8c699bc5e762c1cca2ded100cd20762c5ba56091dea0821f', 'new': 'b8677972689e2d7fb531bad2adf8f4893f17892825c42bfe0973c6266c770b7b', 'body': ''}, 'notification_text.ps1': {'old': None, 'new': '5262f4979b31594ed29661516411568f984e9b273e5004345402da4039c3af3e', 'body': ''}, 'test_notification_text.ps1': {'old': None, 'new': '5b91529047568a3667b7d477f378b1266a7eff96596b5269bbe06c06c9a5bc41', 'body': ''}}
def replace(p,raw,stat=None):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.notify-text-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),stat.st_mode&0o777 if stat else 0o644)
            if stat:os.fchown(f.fileno(),stat.st_uid,stat.st_gid)
        os.replace(name,p)
    finally:Path(name).unlink(missing_ok=True)
def main():
    assert os.geteuid()==0,'Root required'
    root=Path('/opt/fh6/repo/automation');store=Path('/var/lib/fh6');prepared={}
    pwsh=shutil.which('pwsh');assert pwsh,'PowerShell is required'
    for n,m in MANIFEST.items():
        p=root/n;assert not p.is_symlink(),'Unexpected symlink'
        before=p.read_bytes() if p.exists() else None
        sha=hashlib.sha256(before).hexdigest() if before is not None else None
        assert sha==m['old'],'Unexpected version: '+n+'; nothing changed'
        raw=base64.b64decode(m['body']);assert hashlib.sha256(raw).hexdigest()==m['new']
        prepared[n]=(before,p.stat() if p.exists() else None,raw)
    lockpath=store/'runner.lock';assert not lockpath.is_symlink()
    with lockpath.open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        backup=store/'repairs'/('notification-text-'+str(time.time_ns()));backup.mkdir(mode=0o700)
        candidate=backup/'candidate';candidate.mkdir(mode=0o700)
        for n,(before,stat,raw) in prepared.items():
            if before is not None:
                saved=backup/n;saved.write_bytes(before);saved.chmod(0o600)
            (candidate/n).write_bytes(raw)
        # Parse all scripts and execute only isolated text formatting tests.
        parse="$errors=$null;$tokens=$null;Get-ChildItem -LiteralPath '"+str(candidate)+"' -Filter '*.ps1' | ForEach-Object { $null=[System.Management.Automation.Language.Parser]::ParseFile($_.FullName,[ref]$tokens,[ref]$errors);if($errors.Count){throw 'PowerShell parse failed'} }"
        subprocess.run([pwsh,'-NoProfile','-Command',parse],check=True,timeout=30)
        subprocess.run([pwsh,'-NoProfile','-File',str(candidate/'test_notification_text.ps1')],check=True,timeout=30)
        applied=[]
        try:
            for n,(before,stat,raw) in prepared.items():replace(root/n,raw,stat);applied.append(n)
        except Exception:
            for n in reversed(applied):
                before,stat,_=prepared[n]
                if before is None:(root/n).unlink(missing_ok=True)
                else:replace(root/n,before,stat)
            raise
        print('NOTIFICATION_TEXT_INSTALLED concise push; full guarded results retained; no notification sent',flush=True)
        print('BACKUP='+str(backup),flush=True)
if __name__=='__main__':main()
